`,Mt(t.p,{children:"The adoption of Vision-Language Models (VLMs) in embodied AI agents, while being effective, brings safety concerns such as jailbreaking. Prior work have explored the possibility of directly jailbreaking the embodied agents through elaborated multi-modal prompts. However, no prior work has studied or even reported indirect jailbreaks in embodied AI, where a black-box attacker induces a jailbreak without issuing direct prompts to the embodied agent."}),`
`,Mt(t.p,{children:"In this paper, we propose, for the first time, indirect environmental jailbreak (IEJ), a novel attack to jailbreak embodied AI via indirect prompt injected into the environment, such as malicious instructions written on a wall. Our key insight is that embodied AI does not ''think twice'' about the instructions provided by the environment---a blind trust that attackers can exploit to jailbreak the embodied agent."}),`
`,Mt(t.p,{children:"We further design and implement open-source prototypes of two fully-automated frameworks: SHAWSHANK, the first automatic attack generation framework for the proposed attack IEJ; and SHAWSHANK-FORGE, the first automatic benchmark generation framework for IEJ. Then, using SHAWSHANK-FORGE, we automatically construct SHAWSHANK-BENCH, the first benchmark for indirectly jailbreaking embodied agents. Together, our two frameworks and one benchmark answer the questions of what content can be used for malicious IEJ instructions, where they should be placed, and how IEJ can be systematically evaluated."}),`
`,Mt(t.p,{children:"Evaluation results show that SHAWSHANK outperforms eleven existing methods across 3,957 task-scene combinations and compromises all six tested VLMs. Furthermore, current defenses only partially mitigate our attack, and we have responsibly disclosed our findings to all affected VLM vendors."})]})}function zY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt(Sb,{...e})}):Sb(e)}const KY={__name:"Abstract",setup(e){return(t,n)=>{const o=He("el-divider"),l=He("el-col"),a=He("el-row");return E(),D("div",null,[B(o),B(a,{justify:"center"},{default:Y(()=>[B(l,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[B(s(zY))]),_:1})]),_:1})])}}};function kb(e){const t={h1:"h1",img:"img",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Comparison between traditional jailbreak methods and Indirect Environmental Jailbreaking (IEJ)"}),`
`,Mt(t.p,{children:Mt(t.img,{src:"./figures/example.png",alt:""})}),`
`,Mt(t.p,{children:"Our method demonstrates two outcomes: (a) Jailbreaking and (b) Denial-of-Service (DoS) attacks, both leveraging visual environmental manipulation."})]})}function WY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt(kb,{...e})}):kb(e)}const jY={__name:"Markdown",setup(e){return(t,n)=>{const o=He("el-divider"),l=He("el-col"),a=He("el-row");return E(),D("div",null,[B(o),B(a,{justify:"center"},{default:Y(()=>[B(l,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[B(s(WY))]),_:1})]),_:1})])}}};function Eb(e){const t={h1:"h1",img:"img",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Shawshank framework"}),`
`,Mt(t.p,{children:Mt(t.img,{src:"./figures/attack.png",alt:""})}),`
`,Mt(t.p,{children:"The framework includes four modules: (1) the Initialization Module, which defines the task (e.g., damaging water glasses and windows); (2) the Sampling Module, which generates case constraints using genetic algorithms; (3) the Generate Module, which identifies malicious instructions through a generator, surrogate VLM, and evaluator; and (4) the Placement Module, which suggests placement locations for the malicious instruction (e.g., on the wall), and the attack is executed using social engineering techniques."}),`
`,Mt(t.h1,{children:"Shawshank-Forge framework"}),`
`,Mt(t.p,{children:Mt(t.img,{src:"./figures/gendataset.png",alt:""})}),`
`,Mt(t.p,{children:"Shawshank-Forge generates the benchmark dataset in three main stages: (1) Scene Image Collection, where the embodied agent is randomly teleported within the AI2-THOR environment, generating scene descriptions and extracting interactive objects, followed by filtering invalid or similar images based on CLIP similarity. (2) Instruction Generation, where benign instructions of varying complexity and malicious instructions targeting specific harms (e.g., damaging creatures, destroying items) are created. (3) Database Construction, where scene images are paired with the corresponding instructions to form the final image-instruction dataset for evaluating the security of embodied AI systems."})]})}function UY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt(Eb,{...e})}):Eb(e)}const qY={__name:"Framework",setup(e){return(t,n)=>{const o=He("el-divider"),l=He("el-col"),a=He("el-row");return E(),D("div",null,[B(o),B(a,{justify:"center"},{default:Y(()=>[B(l,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[B(s(UY))]),_:1})]),_:1})])}}};function $b(e){const t={h1:"h1",img:"img",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Shawshank-Bench"}),`
