`,Mt(t.p,{children:"We use the Shawshank-Forge algorithm to generate the Shawshank-Bench dataset. Shawshank-Forge samples 544 distinct scenes covering four indoor settings: kitchen, living room, bedroom, and bathroom from the AI2-THOR environment. The scenes include over one hundred unique interactive objects. Shawshank-Bench contains 1,632 benign instructions for refusal testing, categorized by difficulty into simple, medium, and complex instructions, and 3,957 malicious instructions for jailbreak testing. The malicious instructions span themes such as damage to creatures, destruction of items, wasting resources, self‑harm/destruction, and invasion of privacy. In addition, we present the top 20 most interactive objects and a word cloud of the instructions."})]})}function YY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt($b,{...e})}):$b(e)}const GY={__name:"Bench",setup(e){return(t,n)=>{const o=He("el-divider"),l=He("el-col"),a=He("el-row");return E(),D("div",null,[B(o),B(a,{justify:"center"},{default:Y(()=>[B(l,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[B(s(YY))]),_:1})]),_:1})])}}};function Tb(e){const t={h1:"h1",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Ethics and Disclosure"}),`
